char	**mapa;
char	**original_mapa;

int	row_count = 0;
int	row_len = 0;


int	row;
int	col;


int	position = 1;
int	out_of_bounds = 0;

int	repeat = 0;
int	is_loop = 0;

//**********************************
//**********************************

void	map_counter()	//dimension del mapa
{
	int	i = 0;
	int	j = 0;
	
	while (mapa[i] != 0)
	{
		row_count++;
		i++;
	}
	while (mapa[0][j] != '\0')
	{
		row_len++;
		j++;
	}
}

//**********************************
//**********************************


char	**map_splitter(char *input) //split el input
{
	char	**culo;
	
	culo = ft_split(input, ';');
	return (culo);
}


