//**********************************



void	init_finder()	//encontrar posicion inicial
{
	int	i;
	int	j;
	
	printf("se ejecuta?\n");
	
	i = 0;
	j = 0;

	
	while (i < row_count)
	{
		j = 0;
		while (j < row_len)
		{
		
			
			//printf ("%c", mapa[i][j]);
			
				
				
			if (mapa[i][j] == '^')
			{
				row = i;
				col = j;
			}
			j++;
		}
		//printf("\n");
		
		//printf("%s\n", mapa[i]);
		i++;
	}
}


//**********************************
//**********************************

void	go_up()
{
	while (row >= 0)
	{
		if (row == 0)
		{
			out_of_bounds = 1;
			return ;
		}
		if (mapa[row - 1][col] == '#' || mapa[row - 1][col] == 'O')
		{
			mapa[row][col] = '>';
			return ;
		}
		if (mapa[row-1][col] == '.')
			position++;
		if (mapa[row-1][col] == 'X')
			repeat++;
		mapa[row][col] = 'X';
		row--;
		mapa[row][col] = '^';
	}
}

void	go_right()
{
	while (col < row_len)
	{
		if (col == row_len - 1)
		{
			out_of_bounds = 1;
			return ;
		}
		if (mapa[row][col + 1] == '#' || mapa[row][col + 1] == 'O')
		{
			mapa[row][col] = 'v';
			return ;
		}
		if (mapa[row][col + 1] == '.')
			position++;
		if (mapa[row][col + 1] == 'X')
			repeat++;
		mapa[row][col] = 'X';
		col++;
		mapa[row][col] = '>';
	}
}


void	go_down()
{
	while (row < row_count)
	{
		if (row == row_count - 1)
		{
			out_of_bounds = 1;
			return ;
		}
		if (mapa[row + 1][col] == '#' || mapa[row + 1][col] == 'O')
		{
			mapa[row][col] = '<';
			return ;
		}
		if (mapa[row + 1][col] == '.')
			position++;
		if (mapa[row + 1][col] == 'X')
			repeat++;
		mapa[row][col] = 'X';
		row++;
		mapa[row][col] = 'v';
	}
}


void	go_left()
{
	while (col >= 0)
	{
		if (col == 0)
		{
			out_of_bounds = 1;
			return ;
		}
		if (mapa[row][col - 1] == '#' || mapa[row][col - 1] == 'O')
		{
			mapa[row][col] = '^';
			return ;
		}
		if (mapa[row][col - 1] == '.')
			position++;
		if (mapa[row][col - 1] == 'X')
			repeat++;
		mapa[row][col] = 'X';
		col--;
		mapa[row][col] = '<';
	}
}




//***********************************
//***********************************


void	run()
{
	repeat = 0;
	out_of_bounds = 0;
	while (out_of_bounds == 0)
	{
		if (repeat >= (row_count * row_len))
		{
			is_loop++;
			return ;
		}	
		if (mapa[row][col] == '^')
			go_up();
		if (mapa[row][col] == '>')
			go_right();
		if (mapa[row][col] == 'v')
			go_down();
		if (mapa[row][col] == '<')
			go_left();
	}
}

//***********************************
//***********************************
void	map_init()
{
	int	i;
	int	j;
	
	i = 0;
	j = 0;
	while (i < row_count)
	{
		j = 0;
		while (j < row_len)
		{
			mapa[i][j] = original_mapa[i][j];
			j++;
		}
		i++;
	}
}
