//***********************************

int	main()
{
	
	int	i;
	int	j;
	
	int	try;
	try = 0;
	
	i = 0;
	j = 0;
	
	printf("el main no casca\n");
	mapa = ft_split(input, ';');
	original_mapa = ft_split(input, ';');
	printf("split funciona");
	map_counter();
	printf("dimensiones: %d : %d\n", row_count, row_len);
	init_finder();
	printf("posicion inicial : (%d , %d)\n", row, col);
	
	
	while (i < row_count)
	{
		j = 0;
		while (j < row_len)
		{
		
			
			map_init();
			init_finder();
			
			if (i == row && j == col)
			{
				j++;
				continue ;
			}
			
			mapa[i][j] = 'O';
			repeat = 0;
			//*****************
			try++;
			printf("try %d __ loop number: %d\n", try, is_loop);
			//*****************
			//mapa[6][3] = 'O';
			run();
			//mapa[6][3] = '.';
			//mapa[9][7] = 'O';
			//run();
			//mapa[9][7] = '.';
			
			
			j++;
		}
		i++;
	}
	printf("veces que peta: %d", is_loop);
}
